/// <summary>
/// parmfromAutomation
/// </summary>
/// <param name = "_metFromAutomation">_metFromAutomation</param>
/// <returns>fromAutomation</returns>
public boolean metParmFromAutomation(boolean _metFromAutomation = metFromAutomation)
{
    metFromAutomation = _metFromAutomation;
    return metFromAutomation;
}

    /// <summary>
    /// Updates invoice file information and payment status for payments returned by query.
    /// </summary>
    private void METUpdateLedgerJournalTrans()
    {
        QueryRun                metQueryRun = new QueryRun(query);
        VendPaymModeTable       metVendPaymModeTable = VendPaymModeTable::find(custVendPaymModeTable.paymMode);

        if (metVendPaymModeTable.PaymMode != VendParameters::find().METPayPaymMode)
        {
            return;
        }

        ttsbegin;

        while (metQueryRun.next())
        {
            LedgerJournalTrans ledgerJournalTrans = metQueryRun.get(tablenum(LedgerJournalTrans));
            if (ledgerJournalTrans.PaymentStatus == CustVendPaymStatus::METDueDate)
            {
                ledgerJournalTrans.PaymentStatus = CustVendPaymStatus::METDueDateSent;
            }
            else if (ledgerJournalTrans.PaymentStatus == CustVendPaymStatus::METWithdraw)
            {
                ledgerJournalTrans.PaymentStatus = CustVendPaymStatus::METWithdrawSent;
            }
            else if (ledgerJournalTrans.PaymentStatus == CustVendPaymStatus::METResend)
            {
                ledgerJournalTrans.PaymentStatus = CustVendPaymStatus::METResendSent;
            }
            ledgerJournalTrans.METInvFileGenerated = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
            ledgerJournalTrans.METInvFileNumber = metVendPaymModeTable.LastSequenceNumToday;
            ledgerJournalTrans.update();
        }

        ttscommit;
    }
